    def display_image(self, thumbnail):
        if thumbnail.is_broken(): # defektes Bild/Video: Doppelklick, Return, Textzeile und Druck laufen alle hier durch
            print("Datei nicht lesbar, keine Detailansicht: " + thumbnail.getFile())
            return
        file = thumbnail.getShowfile()
        if file == "none":
            # No preview available (e.g. RAW without an accompanying JPEG,
            # or USE_JPEG without a matching JPEG). On double click the
            # detail view should still open, using the original file so
            # the user can see the image.
            file = thumbnail.getFile()        # wenn das Bild schon in einem Fenster angezeigt wird, dann verwenden wir dieses
        if file in self.dict_file_image:
            print ("FSImage exists for file: " + file) if self.debug else True
            fs_image = self.dict_file_image[file]
            fs_image.activate()
        else: # ein neues Objekt anlegen und in dict_file_image eintragen
            if file != 'none':
                print ("FSImage does not exist for file: " + file) if self.debug else True
                if thumbnail.is_video():
                    self.stop_all_players() # we dont want noise from players in Main Window
                    fs_image = FV.MyFSVideo(
                        file = file, 
                        thumbnail = thumbnail, 
                        caller = self,
                        str_title_prefix = "",
                        str_include = "Include",
                        str_exclude = "Exclude",
                        str_included = "Included",
                        str_excluded = "Excluded",
                        temp_dir = Globals.temp_files_path,
                        num_thumbnails = Globals.num_video_thumbnails, 
                        mpv_path = Globals.mpv_path, 
                        ffprobe_path = Globals.ffprobe_path,
                        debug = self.debug
                    )
                    
                else: # STILL    
                    fs_image = FS.MyFSImage(
                        file = file, 
                        thumbnail = thumbnail, 
                        caller = self,
                        str_title_prefix = "Dateimeister: ", 
                        str_include = "Include",
                        str_exclude = "Exclude",
                        str_included = "Included",
                        str_excluded = "Excluded",
                        debug = self.debug
                    )

                self.dict_file_image[file] = fs_image

