    def get_thumbnail_by_position(self, canvas_x, canvas_y):
        index = None
        thumbnail = None
        if Globals.imagetype != "":
            # binary search
            left  = 0
            right = len(Globals.thumbnails[Globals.imagetype]) - 1
            result = -1
            while left <= right:
                mid = (left + right) // 2
                start = Globals.thumbnails[Globals.imagetype][mid].getStart() - (Globals.gap + 1)
                end   = Globals.thumbnails[Globals.imagetype][mid].getEnd()
                if start <= canvas_x and end >= canvas_x:
                    result = mid
                    break
                elif start > canvas_x:
                    right = mid - 1
                else:
                    left = mid + 1
            if result >= 0:
                thumbnail = Globals.thumbnails[Globals.imagetype][result]
                index = result
        else: # imagetype not available
            thumbnail = None
            index = None
        return (thumbnail, index)
 
    def get_camera_xml(self, camera=None):
        """
        Build the flat per-type / per-suffix dictionaries for the currently
        selected camera. These dicts feed generate() and display_images(),
        which index them as dict_subdirs[type] and dict_process_image[suffix].

        The data itself comes from the per-camera accessors in
        dateimeister_config_xml; the flat top-level nodes in the xml are no
        longer read.

        camera: the camera whose data to load.
                - If None / "", we are called from init(). Fall back to the
                  most recently used camera. In that case (and only then)
                  also update the camera listbox selection and the o_camera
                  entry, because nobody else will.
                - If a camera name is given (from B_camera_press), the caller
                  is responsible for the listbox / o_camera. We must not
                  touch them here.
        """
        initial_call = (camera is None or camera == "")

        ts = strftime("%Y%m%d-%H:%M:%S", time.localtime())
        cameraname = self.diatisch_camera_name
        dict_cameras_usedate = DX.get_cameras_usedate(Globals.config_files_xml)
        if cameraname not in dict_cameras_usedate:
            ctype  = "JPEG"
            suffix = "JPG"
            DX.new_camera_type_suffix(Globals.config_files_xml, cameraname, ctype, suffix, ts)
            suffix = "JPEG"
            DX.new_camera_type_suffix(Globals.config_files_xml, cameraname, ctype, suffix, ts)

        dict_cameras = DX.get_cameras_types_suffixes(Globals.config_files_xml)
        dict_t = {}
        for camera_name in dict_cameras:
            dict_t[camera_name] = {}
            type_num = 0
            for type_name in dict_cameras[camera_name]:
                type_num += 1
                suffixes = ", ".join(dict_cameras[camera_name][type_name])
                dict_t[camera_name][type_name] = suffixes
                print("Camera: " + camera_name + " Type: " + type_name +
                      " Suffixes: " + suffixes) if self.debug else True
                if len(suffixes) == 0:
                    messagebox.showerror("INIT", "Camera " + camera_name +
                                         " type " + type_name + " no suffix defined")
                    exit()
            if type_num == 0:
                messagebox.showerror("INIT", "Camera " + camera_name + " no type defined")
                exit()

        # --- pick the camera whose data we want in the flat dicts ---
        index_high = 0
        cameraname_high = ""
        if initial_call:
            usedate_high = ""
            index = 0
            for key in dict_cameras_usedate:
                usedate = dict_cameras_usedate[key]
                print("Kamera {:s} usedate:{:s}".format(key, usedate)) if self.debug else True
                if usedate > usedate_high:
                    usedate_high = usedate
                    index_high = index
                    cameraname_high = key
                index += 1
            camera = cameraname_high
        cam_key = camera.upper()

        # --- flat dicts for generate() / display_images() ---
        dict_s = dict(DX.get_subdirs_per_camera(Globals.config_files_xml).get(cam_key, {}))
        for imagetype in dict_s:
            print("Subdir {:s}, {:s}".format(imagetype, dict_s[imagetype])) if self.debug else True

        dict_pi = {}
        pi_per_cam = DX.get_process_image_per_camera(Globals.config_files_xml).get(cam_key, {})
        for type_name, suffix_dict in pi_per_cam.items():
            for suffix_name, process in suffix_dict.items():
                dict_pi[suffix_name] = process
        for t in dict_pi:
            print("Process Image  {:s}, {:s}".format(t, dict_pi[t])) if self.debug else True

        # --- rebuild the camera listbox (always, because cameras may have
        #     changed). Only set the selection and o_camera on initial call:
        #     on a normal call the caller has already set them.
        self.lb_camera.delete(0, END)
        index = 0
        for key in dict_cameras_usedate:
            self.lb_camera.insert(END, key)
            self.dict_lb_camera_index[key] = index
            index += 1
        if initial_call:
            self.lb_camera.selection_clear(0, END)
            self.lb_camera.selection_set(index_high)
            self.clear_textbox(self.o_camera)
            self.insert_text(self.o_camera, cameraname_high)
        self.button_generate.config(state=NORMAL)

        return dict_t, dict_s, dict_pi

    def stop_all_players(self):
        """Stop all running video players and reset the active player.

        Iterates over Globals.thumbnails (all display keys), so it also
        catches players under a combined display key like
        'JPEG-RAW-VIDEO'. The active_video_player field is used by
        tooltip_imagefile to keep track of the currently playing video;
        it is cleared here so the next tooltip_imagefile call does not
        try to stop an already stopped player.
        """
        list_players = []
        for imagetype_key in list(Globals.thumbnails.keys()):
            for t in Globals.thumbnails[imagetype_key]:
                thisplayer = t.getPlayer()
                if thisplayer is not None:
                    if thisplayer.getRun():
                        thisplayer.pstop()
                        list_players.append(thisplayer)
                        print("stop_all_players: stopping {:s}".format(t.getFile())) if self.debug else True
        if self.active_video_player is not None:
            try:
                self.active_video_player.pstop()
            except Exception:
                pass
            self.active_video_player = None
        return list_players

    def release_players(self, keys=None):
        """pstop + destroy all Players in keys (None = all)."""
        for key in (list(Globals.thumbnails.keys()) if keys is None else keys):
            for t in Globals.thumbnails.get(key, []):
                p = t.getPlayer()
                if p is not None:
                    try:
                        p.pstop()
                        p.destroy()
                    except Exception:
                        pass
                    t.setPlayer(None)
        self.active_video_player = None

    def _sort_within_types(self, combined, sort_method):
        """Sort self.dict_source_target[combined] so that all entries of
        one semantic type are consecutive and inside each type by
        sort_method. Uses self.dict_sourcefile_to_type[combined]."""
        typemap = self.dict_sourcefile_to_type.get(combined, {})
        if not typemap:
            # no mapping -> fallback: normal sort
            self.resort(combined, sort_method)
            return

        # groups in the order of Globals.imagetypes_selected
        type_order = {t: i for i, t in enumerate(Globals.imagetypes_selected)}

        def group_key(src):
            t = typemap.get(src)
            return (type_order.get(t, 999), t or "")

        # mtime cache for sorting by modification date
        mtime_cache = {}
        def mtime(path):
            if path not in mtime_cache:
                try:
                    mtime_cache[path] = os.stat(path).st_mtime
                except OSError:
                    mtime_cache[path] = 0.0
            return mtime_cache[path]

        if sort_method in (1, 2):
            inner_key = lambda x: x[0]
        elif sort_method in (3, 4):
            inner_key = lambda x: mtime(x[0])
        else:
            inner_key = None
        inner_reverse = sort_method in (2, 4)

        for d in (self.dict_source_target, self.dict_source_target_jpeg, self.dict_source_target_tooold):
            items = list(d[combined].items())
            if inner_key is not None:
                items.sort(key=inner_key, reverse=inner_reverse)
            items.sort(key=lambda kv: group_key(kv[0]))
            d[combined] = dict(items)

    def write_cmdfile(self, imagetype):
        """Writes ONE copy, ONE delete and ONE delrelpath file for the
        display key `imagetype` (may be 'JPEG-RAW-VIDEO').

        Copy and delete contain the lines of all types in the order of
        self.dict_source_target[imagetype].

        Delrelpath sets '@set OUTDIR=' to the type-specific outdir before
        each type group and then walks the relpaths of that type
        (from dict_relpath_by_type)."""
        ts = strftime("%Y%m%d-%H:%M:%S", time.localtime())
        template_copy       = self.dict_templates["COPY"]
        template_delete     = self.dict_templates["DELETE"]
        template_delrelpath = self.dict_templates["DELRELPATH"]
        template_empty      = self.dict_templates["EMPTY"]
        header = Globals.uncomment + ' generated by dateimeister ' + ts + '\n'

        # --- Copy ---
        cmd_file_full = self.dict_gen_files[imagetype] # filename was already built by generate-method
        thiscmdfile = open(cmd_file_full, 'w')
        thiscmdfile.write(header) 
        dict_files = self.dict_source_target[imagetype]
        for sourcefile in dict_files:
            comment = ""
            do_include = False
            #print(imagetype + ', ' + sourcefile)
            if imagetype in Globals.dict_thumbnails and sourcefile in Globals.dict_thumbnails[imagetype]:
                thumbnail = Globals.dict_thumbnails[imagetype][sourcefile]
                if thumbnail.getState() == EXCLUDE:
                    comment = Globals.uncomment
                else: # we have to incluse this file even if it is too old
                    do_include = True
            # we also have to check if file is too old but only if include us not requqested by thumbnail (manually included)
            if do_include == False:
                if imagetype in self.dict_source_target_tooold and sourcefile in self.dict_source_target_tooold[imagetype]:
                    comment = Globals.uncomment 
            targetfile = dict_files[sourcefile]
            if self.platform == "WINDOWS":
                targetfile = re.sub(r'/', '\\\\', targetfile) # replace / by \
            elif self.platform == "UNIX":
                targetfile = re.sub(r'\\', '/', targetfile) # replace \ by /
            str_ret = template_copy
            str_ret = str_ret.replace('<source>', sourcefile)
            str_ret = str_ret.replace('<target>', targetfile)
            str_ret = re.sub(r'<<<NL>>>', '\n', str_ret) # reconstruct newline in template
            thiscmdfile.write(comment + str_ret + '\n')
        thiscmdfile.close()

        # --- Delete ---
        cmd_file_full = self.dict_gen_files_delete[imagetype] # filename was already built by generate-method
        thiscmdfile = open(cmd_file_full, 'w')
        thiscmdfile.write(header) 
        dict_files = self.dict_source_target[imagetype]
        for sourcefile in dict_files:
            comment = ""
            do_include = False
            #print(imagetype + ', ' + sourcefile)
            if imagetype in Globals.dict_thumbnails and sourcefile in Globals.dict_thumbnails[imagetype]:
                thumbnail = Globals.dict_thumbnails[imagetype][sourcefile]
                if thumbnail.getState() == EXCLUDE:
                    comment = Globals.uncomment
                else: # we have to incluse this file even if it is too old
                    do_include = True
            # we also have to check if file is too old but only if include us not requqested by thumbnail (manually included)
            if do_include == False:
                if imagetype in self.dict_source_target_tooold and sourcefile in self.dict_source_target_tooold[imagetype]:
                    comment = Globals.uncomment 
            targetfile = dict_files[sourcefile]
            if self.platform == "WINDOWS":
                targetfile = re.sub(r'/', '\\\\', targetfile) # replace / by \
            elif self.platform == "UNIX":
                targetfile = re.sub(r'\\', '/', targetfile) # replace \ by /
            str_ret = template_delete
            str_ret = str_ret.replace('<source>', sourcefile)
            str_ret = str_ret.replace('<target>', targetfile)
            str_ret = re.sub(r'<<<NL>>>', '\n', str_ret) # reconstruct newline in template
            thiscmdfile.write(comment + str_ret + '\n')
        thiscmdfile.close()
        
        # --- Delrelpath ---
        # One file for all types; '@set OUTDIR' before each type group.
        cmd_file_full = self.dict_gen_files_delrelpath[imagetype] # filename was already built by generate-method
        thiscmdfile = open(cmd_file_full, 'w')
        thiscmdfile.write(header)
        for dateityp in Globals.imagetypes_selected:
            outdir_t = self.dict_outdirs_by_type.get(dateityp, "")
            if not outdir_t:
                continue
            if self.platform == "WINDOWS":
                outdir_cmd = re.sub(r'/', '\\\\', outdir_t) # replace / by \
            elif self.platform == "UNIX":
                outdir_cmd = re.sub(r'\\', '/', outdir_t) # replace \ by /
            else:
                outdir_cmd = outdir_t
            thiscmdfile.write("@set OUTDIR=" + outdir_cmd + '\n')
            for relpath in self.dict_relpath_by_type.get(dateityp, {}):
                str_ret = template_delrelpath
                if self.platform == "WINDOWS":
                    str_ret = str_ret.replace('<trenner>', '\\')
                    relpath_cmd = re.sub(r'/', '\\\\', relpath) # replace / by \
                elif self.platform == "UNIX":
                    str_ret = str_ret.replace('<trenner>', '/')
                    relpath_cmd = re.sub(r'\\', '/', relpath) # replace \ by /
                else:
                    relpath_cmd = relpath
                str_ret = str_ret.replace('<relpath>', relpath_cmd)
                str_ret = re.sub(r'<<<NL>>>', '\n', str_ret) # reconstruct newline in template
                thiscmdfile.write(str_ret + '\n')
        # add the script
        str_ret = template_empty
        str_ret = re.sub(r'<<<NL>>>', '\n', str_ret) # reconstruct newline in template
        for ii in str_ret.split('\n'):
            thiscmdfile.write(ii + '\n')
        thiscmdfile.close()

    def close_handler(self): #called when window is closing: unbind event handlers send closing event and destroy window
        # 20260915 important to avoid call after object is destroyed!
        Globals.eventManager.unbind("FileStateChanged", self.on_file_state_changed)
        Globals.eventManager.unbind("Closing", self.on_closing)
        Globals.eventManager.unbind("PrintRequestEvent", self.handle_print_request)
        self.dict_visible_id_thumbnail_video.clear()
        self.close_child_windows()
        self.root.destroy()

